// Demo: Code City Metaphors — code city layout
var mods=[];for(var i=0;i<1;i++){mods.push({name:'mod'+i,h:10+((i*37+1)%80),w:5+((i*13)%15)});}
console.log('technique: Code City Metaphors');console.log('modules: '+mods.length);
var big=mods.slice().sort(function(a,b){return b.h-a.h;})[0];
console.log('tallest building: '+big.name+' ('+big.h+' floors = lines of code)');
console.log('walk the city to grasp the architecture');

