// Demo: Gesture Navigation — heat overlay on 30 files
var files=[];for(var i=0;i<30;i++){files.push({f:'f'+i+'.js',bugs:((i*29+5)%6)});}
var hot=files.filter(function(f){return f.bugs>=4;});
console.log('technique: Gesture Navigation');console.log('files: '+files.length+', hot (4+ bugs): '+hot.length);
console.log('hot files glow red in AR: '+hot.slice(0,5).map(function(f){return f.f;}).join(', '));

